const icon = (name, cls='') => { const svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.setAttribute('class',`svg-icon ${cls}`.trim());const path=document.createElementNS(NS,'path');path.setAttribute('d',icons[name]||icons.file);svg.append(path);return svg; };
const node=(tag,cls='',text='')=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined&&text!==null)n.textContent=String(text);return n;};
const setChildren=(target,...children)=>{target.replaceChildren(...children.filter(Boolean));return target;};
const button=(label,variant='button-secondary',glyph=null)=>{const b=node('button',`button ${variant}`);b.type='button';if(glyph)b.append(icon(glyph));b.append(node('span','',label));return b;};
const statusClass=s=>s==='APPROVED'?'status-approved':s==='PENDING'?'status-pending':s==='REJECTED'?'status-rejected':'status-info';
const badge=(status,label=status)=>{const b=node('span',`badge ${statusClass(status)}`);b.append(node('i','badge-dot'),node('span','',label));return b;};
const formatTime=value=>{if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});};
const escText=v=>v===undefined||v===null||v===''?'—':String(v);

