function toast(message,type='success'){const t=node('div',`toast ${type==='error'?'error':''}`);t.append(icon(type==='error'?'alert':'check'),node('span','',message));$('#toast-region').append(t);setTimeout(()=>t.remove(),3600);}
async function api(path,options={}){const response=await fetch(API+path,options);if(!response.ok){let detail=`Request failed (${response.status})`;try{detail=(await response.json()).detail||detail;}catch{}throw new Error(detail);}return response.headers.get('content-type')?.includes('application/json')?response.json():response.text();}
function setPage(name){$$('.page').forEach(p=>p.classList.toggle('hidden',p.id!==`page-${name}`));$$('.nav-item').forEach(b=>{const active=b.dataset.page===name;b.classList.toggle('is-active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const names={new:['New submission','Run a vendor through the onboarding checks.'],live:['Live run','Follow each verification as it happens.'],dashboard:['Dashboard','Monitor decisions, review workload, and recent runs.'],rules:['Review rules','A transparent guide to how VendorGate routes each submission.']};$('#main').dataset.page=name;closeMobile();if(name==='dashboard')loadDashboard();if(name==='live'&&!currentRun)renderLiveEmpty();}
function closeMobile(){$('body').classList.remove('mobile-open');$('#menu-open').setAttribute('aria-expanded','false');$('#mobile-overlay').classList.add('hidden');}
function openMobile(){$('body').classList.add('mobile-open');$('#menu-open').setAttribute('aria-expanded','true');$('#mobile-overlay').classList.remove('hidden');}

function emptySubmission(){return {vendor_type:'company',legal_name:'',trade_name:'',country:'US',address:{line1:'',city:'',postal_code:'',country:'US'},contact:{name:'',email:'',phone:'',website:''},tax:{tax_id_type:'EIN',tax_id:''},bank:{account_holder_name:'',bank_name:'',iban:'',account_number:'',routing_or_ifsc:'',bank_country:'US',currency:'USD'},documents:[]};}
function pathValue(obj,path){return path.split('.').reduce((v,k)=>v?.[k],obj);}
function putPath(obj,path,value){const parts=path.split('.');let p=obj;for(const key of parts.slice(0,-1)){p[key]??={};p=p[key];}p[parts.at(-1)]=value;}
function fieldControl(path,label,type,options=[],value=''){
  const wrap=node('div','field');const id=`f-${path.replaceAll('.','-')}-${Math.random().toString(36).slice(2,6)}`;const lab=node('label','',label);lab.htmlFor=id;wrap.append(lab);
  let control;if(type==='select'||type==='country'){control=node('select','input-control');let vals=type==='country'?['US','IN','GB','DE','FR','CA','AU','SG','Other']:options;for(const v of vals){const o=node('option','',v);o.value=v;control.append(o);}}else{control=node('input','input-control');control.type=type;control.placeholder=label==='Legal name'?'Registered legal name':'';}
  control.id=id;control.dataset.path=path;control.value=value??'';control.addEventListener('input',formChanged);control.addEventListener('change',formChanged);wrap.append(control);
  const help=path==='tax.tax_id_type'||path==='tax.tax_id'?node('span','helper',path==='tax.tax_id_type'?'Select the identifier used in the vendor’s country.':taxHint()):null;if(help)wrap.append(help);return wrap;
}
function taxHint(){const t=$('[data-path="tax.tax_id_type"]')?.value;return ({EIN:'Expected format: XX-XXXXXXX',PAN:'Expected format: AAAAA9999A',GSTIN:'15-character GSTIN with check digit',VAT:'Country-specific VAT number',COMPANY_NUMBER:'8 alphanumeric characters'})[t]||'Use the country-specific tax format.';}
function renderForm(data){currentSubmission=structuredClone(data||emptySubmission());const root=$('#form-cards');root.replaceChildren();for(const group of fieldsByGroup){const card=node('section',`card form-card ${group.id==='bank'?'form-card-wide':''}`);card.setAttribute('aria-labelledby',`heading-${group.id}`);const head=node('div','card-heading');const title=node('div','card-title-wrap');const ic=node('span','card-icon');ic.append(icon(group.icon));title.append(ic,node('div',''));title.lastChild.append(node('h2','',group.title));head.append(title);card.append(head);const grid=node('div','field-grid');for(const [path,label,type,opts] of group.fields){const val=pathValue(currentSubmission,path);grid.append(fieldControl(path,label,type,opts||[],val));}card.append(grid);root.append(card);}
  const docCard=node('section','card form-card form-card-wide');const h=node('div','card-heading');const ttl=node('div','card-title-wrap');const ic=node('span','card-icon');ic.append(icon('file'));ttl.append(ic,node('div',''));ttl.lastChild.append(node('h2','',`Documents (${currentSubmission.documents?.length||0})`),node('p','helper','Add structured document metadata for the review.'));h.append(ttl);docCard.append(h);const list=node('div','document-list');list.id='document-list';docCard.append(list);for(const d of currentSubmission.documents||[])addDocumentRow(d,false);const actions=node('div','document-actions');const add=button('Add document','button-secondary button-small','plus');add.addEventListener('click',()=>{addDocumentRow({},true);formChanged();});actions.append(add);docCard.append(actions);root.append(docCard);$('#json-editor').value=JSON.stringify(currentSubmission,null,2);validateJson();}
function addDocumentRow(doc={},focus=true){const row=node('div','document-row');const defs=[['type','Document type','select',['tax_certificate','bank_letter','incorporation_certificate','w9','gst_certificate']],['filename','Filename','text'],['name_on_document','Name on document','text'],['issuing_country','Issuing country','country'],['expiry_date','Expiry date','date']];for(const [key,label,type,opts] of defs){const f=fieldControl(`documents.${key}`,label,type,opts,doc[key]||'');const ctl=$('input,select',f);ctl.dataset.docField=key;row.append(f);}const remove=node('button','icon-button remove-document');remove.type='button';remove.setAttribute('aria-label','Remove document');remove.append(icon('trash'));remove.addEventListener('click',()=>{row.remove();formChanged();});row.append(remove);const list=$('#document-list');if(list)list.append(row);else pendingDocumentRows.push(row);if(focus)$('select,input',row)?.focus();return row;}
function collectForm(){const out=emptySubmission();for(const c of $$('[data-path]')){if(c.dataset.path.startsWith('documents.'))continue;putPath(out,c.dataset.path,c.value);}out.documents=$$('.document-row').map(row=>{const d={};for(const c of $$('[data-doc-field]',row))d[c.dataset.docField]=c.value;return d;});if(currentSubmission?.submission_id)out.submission_id=currentSubmission.submission_id;if(currentSubmission?.submitted_at)out.submitted_at=currentSubmission.submitted_at;return out;}
function formChanged(){const out=collectForm();currentSubmission=out;$('#json-editor').value=JSON.stringify(out,null,2);validateJson();const taxHelp=$('[data-path="tax.tax_id"]')?.parentElement.querySelector('.helper');if(taxHelp)taxHelp.textContent=taxHint();}
function syncFormValues(data){currentSubmission=data;for(const c of $$('[data-path]')){if(c.dataset.path.startsWith('documents.'))continue;const v=pathValue(data,c.dataset.path);if(v!==undefined)c.value=v;}const list=$('#document-list');if(list){list.replaceChildren();for(const d of data.documents||[])addDocumentRow(d,false);} }
function validateJson(){const text=$('#json-editor').value,ind=$('#json-validity');try{JSON.parse(text);ind.textContent='Valid JSON';ind.classList.remove('is-invalid');ind.classList.remove('hidden');return true;}catch(e){const match=e.message.match(/position (\d+)/i);const pos=match?Number(match[1]):0;const line=text.slice(0,pos).split('\n').length;ind.textContent=`Invalid JSON at line ${line}`;ind.classList.add('is-invalid');ind.classList.remove('hidden');return false;}}
function activateEditor(tab){const json=tab==='json';$('#tab-form').classList.toggle('is-selected',!json);$('#tab-json').classList.toggle('is-selected',json);$('#tab-form').setAttribute('aria-selected',String(!json));$('#tab-json').setAttribute('aria-selected',String(json));$('#panel-form').classList.toggle('hidden',json);$('#panel-json').classList.toggle('hidden',!json);$('#json-validity').classList.toggle('hidden',!json);if(json)$('#json-editor').focus();}
function humanSample(key){return sampleMeta[key]||[key.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()),'Sample vendor submission','PENDING'];}
function renderSamples(){const grid=$('#sample-grid');grid.replaceChildren();const keys=Object.keys(samples);$('#sample-count').textContent=`${keys.length} examples`;for(const key of keys){const [title,desc,outcome]=humanSample(key);const card=node('button','sample-card');card.type='button';card.dataset.sample=key;card.setAttribute('aria-pressed',String(key===selectedSample));const top=node('div','sample-card-top');top.append(node('span','sample-title',title),badge(outcome,outcome.charAt(0)+outcome.slice(1).toLowerCase()));card.append(top,node('p','sample-description',desc));card.addEventListener('click',()=>selectSample(key));grid.append(card);}}
function selectSample(key){if(!samples[key])return;selectedSample=key;parentForResubmit=null;renderForm(samples[key]);renderSamples();activateEditor('form');}
function resetForm(){parentForResubmit=null;selectedSample='';renderForm(emptySubmission());renderSamples();$('#run-process').disabled=false;$('#run-process').classList.remove('button-loading');$('#run-process').querySelector('span:last-child').textContent='Run process';}

function stageRow(id,name){const row=node('div','step-row idle');row.id=`stage-${id}`;row.dataset.stage=id;row.dataset.status='idle';row.setAttribute('aria-expanded','false');const status=node('span','step-status');status.append(icon('clock'));const main=node('div','step-main');main.append(node('div','step-name',name),node('div','step-summary','Waiting for this check'));const dur=node('span','step-duration','');const chev=node('button','step-chevron');chev.type='button';chev.setAttribute('aria-label',`Expand ${name} evidence`);chev.setAttribute('aria-expanded','false');chev.append(icon('chevron'));const evidence=node('div','step-evidence');row.append(status,main,dur,chev,evidence);chev.addEventListener('click',()=>{const open=row.getAttribute('aria-expanded')!=='true';row.setAttribute('aria-expanded',String(open));chev.setAttribute('aria-expanded',String(open));});return row;}
function renderLiveEmpty(){const root=$('#live-content');root.replaceChildren();const e=node('div','empty-state empty-live');const i=node('div','empty-icon');i.append(icon('activity'));e.append(i,node('h3','', 'No run selected'),node('p','','Start a vendor review to see live checks and decision evidence here.'));const b=button('Go to New submission','button-primary','plus');b.addEventListener('click',()=>setPage('new'));e.append(b);root.append(e);}
function prepareLive(payload){currentRun=null;currentSubmission=payload;currentEvents=[];const root=$('#live-content');root.replaceChildren();const vendor=node('section','card live-vendor-card');const line=node('div','live-vendor-line');const nam=node('div','live-vendor-name',payload?.legal_name||'New vendor');const country=node('span','country-chip',payload?.country||'—');nam.append(country);line.append(nam,node('span','subtle-label','Validating submission'));const progressHead=node('div','progress-head');progressHead.append(node('span','','Verification progress'),node('span','progress-label','0 of 10 complete'));const track=node('div','progress-track');const fill=node('div','progress-fill');fill.style.width='0%';track.append(fill);vendor.append(line,progressHead,track);const stepCard=node('section','card stepper-card');stepCard.setAttribute('aria-label','Verification steps');stepCard.setAttribute('role','list');const list=node('div','stepper-list');for(const [id,name] of stages){const row=stageRow(id,name);row.setAttribute('role','listitem');list.append(row);}stepCard.append(list);root.append(vendor,stepCard);}
function setStageEvent(event){const row=$(`#stage-${CSS.escape(event.stage_id)}`);if(!row)return;const name=event.name||stages.find(x=>x[0]===event.stage_id)?.[1]||event.stage_id;const status=event.status||'info';row.classList.remove('idle','running','pass','warn','fail','info');row.classList.add(status);row.dataset.status=status;$('.step-status',row).replaceChildren(icon(status==='running'?'clock':status==='pass'?'check':status==='warn'?'alert':status==='fail'?'x':'file'));$('.step-name',row).textContent=name;$('.step-summary',row).textContent=event.summary|| (status==='running'?'Running check…':'Check complete');$('.step-duration',row).textContent=status==='running'?'':`${Number(event.duration_ms||0)} ms`;const completed=$$('.step-row', $('#live-content')).filter(r=>['pass','warn','fail','info'].includes(r.dataset.status)).length;$('.progress-label').textContent=`${completed} of 10 complete`;$('.progress-fill').style.width=`${completed*10}%`;if(status!=='running')fillEvidence(row,event);}
function flattenEvidence(obj,prefix='',out=[]){if(!obj||typeof obj!=='object'){out.push([prefix,escText(obj)]);return out;}if(Array.isArray(obj)){if(!obj.length)out.push([prefix,'None']);else obj.forEach((v,i)=>flattenEvidence(v,`${prefix}[${i}]`,out));return out;}const entries=Object.entries(obj);if(!entries.length)out.push([prefix,'None']);else entries.forEach(([k,v])=>flattenEvidence(v,prefix?`${prefix}.${k}`:k,out));return out;}
function fillEvidence(row,event){const target=$('.step-evidence',row);target.replaceChildren();const source=event.evidence||{};const findings=[...(Array.isArray(event.details)?event.details:[])];const list=node('div','finding-list');for(const f of findings){const item=node('div','finding-row');if(f.evidence?.rule_id)item.append(node('span','rule-id',f.evidence.rule_id));if(f.severity&&f.severity!=='none')item.append(node('span',`badge severity-${f.severity}`,f.severity));item.append(node('span','',f.summary||String(f)));list.append(item);}if(findings.length)target.append(list);const clean={...source};const ruleIds=clean.rule_ids;if(ruleIds)delete clean.rule_ids;if(clean.rule_id){const rule=node('span','rule-id',clean.rule_id);target.append(rule);delete clean.rule_id;}const pairs=flattenEvidence(clean).filter(([k])=>k);if(pairs.length){const dl=node('dl','evidence-grid');for(const [k,v] of pairs){const wrap=node('div','evidence-pair');wrap.append(node('dt','',k),node('dd','',v));dl.append(wrap);}target.append(dl);}const raw=button('View raw JSON','button-ghost button-small');raw.classList.add('raw-toggle');raw.setAttribute('aria-expanded','false');const pre=node('pre','raw-block hidden',JSON.stringify(event,null,2));raw.addEventListener('click',()=>{const open=pre.classList.toggle('hidden')===false;raw.setAttribute('aria-expanded',String(open));raw.querySelector('span').textContent=open?'Hide raw JSON':'View raw JSON';});target.append(raw,pre);}
function renderDecision(run,root=$('#live-content'),compact=false){const result=run.result;const decision=node('section',`decision-card ${result.status.toLowerCase()}`);decision.setAttribute('aria-live','polite');const top=node('div','decision-top');const heading=node('div');heading.append(node('h2','decision-title',compact?'Decision':'Decision summary'),node('div','decision-meta',`${run.payload?.legal_name||run.vendor||'Vendor'} · ${run.payload?.country||run.country||'—'} · rule-based`));top.append(heading,badge(result.status,result.status[0]+result.status.slice(1).toLowerCase()));decision.append(top);const stats=node('div','decision-stats');const risk=node('div');const rlabel=node('div','risk-label');rlabel.append(node('span','','Risk score'),node('strong','',`${result.risk_score}/100`));const track=node('div','risk-track');const fill=node('div','risk-fill');fill.style.width=`${Math.min(100,Math.max(0,result.risk_score||0))}%`;fill.style.background=result.risk_score<35?'var(--green)':result.risk_score<65?'var(--amber)':'var(--red)';track.append(fill);risk.append(rlabel,track);const confidence=node('div','confidence-box');confidence.append(node('div','confidence-label','Confidence'),node('div','confidence-value',`${result.confidence}%`));stats.append(risk,confidence);decision.append(stats);
  const why=node('div','reason-section');why.append(node('h3','card-title-wrap','Why this decision'));const seenReasons=new Set();const reasons=(result.decision_reasons||[]).filter(r=>{if(r.stage==='decision')return false;const key=String(r.summary||'').trim().toLowerCase();if(seenReasons.has(key))return false;seenReasons.add(key);return true;}).slice(0,5);const ul=node('ul','reason-list');if(!reasons.length){ul.append(node('li','reason-link','No findings. The submission met all configured checks.'));}else for(const reason of reasons){const li=node('li');const link=node('button','reason-link');link.type='button';const rid=reason.evidence?.rule_id||stageRuleIds[reason.stage]?.[0];if(rid)link.append(node('span','rule-id',rid));link.append(node('span','',''+reason.summary));link.addEventListener('click',()=>{const row=$(`#stage-${CSS.escape(reason.stage)}`);row?.scrollIntoView({behavior:reducedMotion()?'auto':'smooth',block:'center'});if(row){row.classList.add('is-highlighted');setTimeout(()=>row.classList.remove('is-highlighted'),1800);row.setAttribute('aria-expanded','true');$('.step-chevron',row).setAttribute('aria-expanded','true');}});li.append(link);ul.append(li);}why.append(ul);decision.append(why);
  const msgTabs=node('div','tab-list message-tabs');msgTabs.setAttribute('role','tablist');const content=node('div','decision-tab-content');const tabs=[['vendor_message','Vendor message'],['internal_note','Internal note'],['raw','Raw JSON'],['audit','Audit log']];const selectTab=(key)=>{msgTabs.replaceChildren();for(const [k,label] of tabs){const b=node('button',`tab-button ${k===key?'is-selected':''}`,label);b.setAttribute('role','tab');b.setAttribute('aria-selected',String(k===key));b.addEventListener('click',()=>selectTab(k));msgTabs.append(b);}renderDecisionTab(key,run,content);};selectTab('vendor_message');decision.append(msgTabs,content);if(!compact){const actions=node('div','message-actions');const copy=button('Copy message','button-secondary button-small','copy');copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(result.vendor_message||'');toast('Vendor message copied.');}catch{toast('Clipboard access is unavailable.','error');}});const download=button('Download report','button-secondary button-small','download');download.addEventListener('click',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(run,null,2)],{type:'application/json'}));a.download=`vendorgate-${run.id||'report'}.json`;a.click();URL.revokeObjectURL(a.href);toast('Report downloaded.');});actions.append(copy,download);decision.append(actions);}return decision;}
function renderDecisionTab(key,run,target){target.replaceChildren();if(key==='raw'){const toggle=button('View raw JSON','button-ghost button-small','file');const pre=node('pre','raw-block hidden',JSON.stringify(run.payload,null,2));toggle.setAttribute('aria-expanded','false');toggle.addEventListener('click',()=>{const open=pre.classList.toggle('hidden')===false;toggle.setAttribute('aria-expanded',String(open));toggle.querySelector('span').textContent=open?'Hide raw JSON':'View raw JSON';});target.append(toggle,pre);return;}if(key==='audit'){const list=node('div','audit-list');for(const e of run.events||[]){const row=node('div','audit-line');row.append(node('span','audit-stage',e.name),node('span','',e.summary),node('span','step-duration',`${e.duration_ms||0} ms`));list.append(row);}target.append(list);return;}const card=node('div','message-card');const meta=node('div','message-meta');meta.append(node('strong','','To'),node('span','',run.payload?.contact?.email||'Vendor contact'),node('strong','','Subject'),node('span','',key==='vendor_message'?`Vendor onboarding — ${run.result.status.toLowerCase()}`:'Procurement review note'));const body=node('p','message-body',key==='vendor_message'?run.result.vendor_message:run.result.internal_note);card.append(meta,body);target.append(card);}
function finishRun(run){currentRun=run;currentSubmission=run.payload;currentEvents=run.events||[];$('#live-nav-dot').classList.add('hidden');const root=$('#live-content');root.replaceChildren();const decision=renderDecision(run);root.append(decision);const vendor=node('section','card live-vendor-card');const line=node('div','live-vendor-line');const nam=node('div','live-vendor-name',run.payload.legal_name||run.vendor);nam.append(node('span','country-chip',run.payload.country||run.country||''));line.append(nam,badge(run.result.status,run.result.status));const progressHead=node('div','progress-head');progressHead.append(node('span','','10 verification stages'),node('span','progress-label','10 of 10 complete'));const track=node('div','progress-track');const fill=node('div','progress-fill');fill.style.width='100%';track.append(fill);vendor.append(line,progressHead,track);const card=node('section','card stepper-card');card.append(node('div','card-heading'),);const list=node('div','stepper-list');for(const event of currentEvents){const row=stageRow(event.stage_id,event.name);row.classList.remove('idle');row.classList.add(event.status);row.dataset.status=event.status;$('.step-status',row).replaceChildren(icon(event.status==='pass'?'check':event.status==='warn'?'alert':event.status==='fail'?'x':'file'));$('.step-summary',row).textContent=event.summary;$('.step-duration',row).textContent=`${event.duration_ms||0} ms`;fillEvidence(row,event);list.append(row);}card.append(list);root.append(vendor,card);if(run.parent_run_id||run.previous_id)loadDiff(run.parent_run_id||run.previous_id,root);if(run.result.status==='PENDING'){const resubmit=button('Resubmit with corrections','button-secondary','rotate-ccw');resubmit.addEventListener('click',()=>{parentForResubmit=run.id;selectSample('');renderForm(run.payload);parentForResubmit=run.id;setPage('new');toast('Edit the submission, then run it to compare the decisions.');});root.insertBefore(resubmit,card);}}
function reducedMotion(){return window.matchMedia('(prefers-reduced-motion: reduce)').matches;}
async function beginRun(payload){const generation=++runGeneration;if(eventSource){eventSource.close();eventSource=null;}activeRunId=null;currentSubmission=payload;currentRun=null;currentEvents=[];drawerRun=null;parentForResubmit=null;closeDrawer();$('#drawer-content').replaceChildren();$('#live-content').replaceChildren();setPage('live');prepareLive(payload);$('#live-nav-dot').classList.remove('hidden');const ctl=$('#run-process');ctl.classList.add('button-loading');ctl.disabled=true;try{const {id}=await api('/api/runs/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(generation!==runGeneration)return;activeRunId=id;const source=new EventSource(`/api/stream/${encodeURIComponent(id)}`);eventSource=source;const isCurrent=()=>generation===runGeneration&&activeRunId===id&&eventSource===source;source.onmessage=async message=>{if(!isCurrent())return;let item;try{item=JSON.parse(message.data);}catch{return;}if(item.done){source.close();try{const run=await api(`/api/runs/${encodeURIComponent(id)}`);if(!isCurrent()||run.id!==id)return;finishRun(run);}catch(e){if(isCurrent())toast(e.message,'error');}if(isCurrent()){eventSource=null;ctl.classList.remove('button-loading');ctl.disabled=false;}return;}setStageEvent(item);};source.onerror=()=>{if(!isCurrent())return;source.close();eventSource=null;ctl.classList.remove('button-loading');ctl.disabled=false;toast('The live event stream disconnected. Refresh runs to review the saved result.','error');};}catch(e){if(generation!==runGeneration)return;ctl.classList.remove('button-loading');ctl.disabled=false;toast(e.message,'error');const err=node('div','inline-error',e.message);$('#live-content').prepend(err);}}

function renderDashboardSkeleton(){const k=$('#dashboard-kpis');k.replaceChildren();for(let i=0;i<6;i++){const c=node('div','kpi-card');c.append(node('div','skeleton','　'),node('div','skeleton','　'),node('div','skeleton','　'));k.append(c);}const content=$('#runs-content');content.replaceChildren(node('div','empty-state','Loading run history…'));}
function makeKpi(title,value,context,ic){const card=node('div','kpi-card');const top=node('div','kpi-top');top.append(node('span','',title));const ico=node('span','kpi-icon');ico.append(icon(ic));top.append(ico);card.append(top,node('strong','kpi-value',value),node('div','kpi-context',context));return card;}
function svgEl(name,attrs={}){const n=document.createElementNS(NS,name);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));return n;}
function drawStatusChart(runs){const target=$('#status-chart');target.replaceChildren();if(!runs.length){target.append(node('div','chart-empty','Run a sample to see decision distribution.'));return;}const counts={APPROVED:0,PENDING:0,REJECTED:0};for(const r of runs)counts[r.status]=(counts[r.status]||0)+1;const total=runs.length;const layout=node('div','chart-layout');const svg=svgEl('svg',{viewBox:'0 0 120 120',class:'donut-svg',role:'img','aria-label':`${counts.APPROVED} approved, ${counts.PENDING} pending, ${counts.REJECTED} rejected`});const colors={APPROVED:'var(--green)',PENDING:'var(--amber)',REJECTED:'var(--red)'};let offset=0;for(const key of Object.keys(counts)){const amount=counts[key];const circle=svgEl('circle',{cx:60,cy:60,r:43,fill:'none',stroke:colors[key],'stroke-width':14,'stroke-dasharray':`${(amount/total)*270} 270`,'stroke-dashoffset':-offset,transform:'rotate(-90 60 60)'});svg.append(circle);offset+=(amount/total)*270;}svg.append(svgEl('circle',{cx:60,cy:60,r:31,fill:'white'}));const text=svgEl('text',{x:60,y:57,'text-anchor':'middle',fill:'var(--text)','font-size':19,'font-weight':600});text.textContent=String(total);svg.append(text);const sub=svgEl('text',{x:60,y:72,'text-anchor':'middle',fill:'var(--muted)','font-size':8});sub.textContent='runs';svg.append(sub);layout.append(svg);const legend=node('div','chart-legend');for(const key of Object.keys(counts)){const row=node('div','legend-item');const sw=node('i','legend-swatch');sw.style.background=colors[key];row.append(sw,node('span','',key.charAt(0)+key.slice(1).toLowerCase()),node('strong','',`${counts[key]} · ${Math.round(counts[key]/total*100)}%`));legend.append(row);}layout.append(legend);target.append(layout);}
function drawTimeChart(runs){const target=$('#time-chart');target.replaceChildren();if(!runs.length){target.append(node('div','chart-empty','Run a sample to see recent activity.'));return;}const map=new Map();for(const r of runs){const d=new Date(r.submitted_at||Date.now());const k=Number.isNaN(d.getTime())?'Unknown':d.toLocaleDateString(undefined,{month:'short',day:'numeric'});map.set(k,(map.get(k)||0)+1);}const points=[...map.entries()].slice(-7),max=Math.max(1,...points.map(x=>x[1]));const w=420,h=132,pad={l:24,r:8,t:8,b:25};const svg=svgEl('svg',{viewBox:`0 0 ${w} ${h}`,class:'bar-chart',role:'img','aria-label':'Runs over time chart'});for(let n=0;n<3;n++){const y=pad.t+(h-pad.t-pad.b)*n/2;svg.append(svgEl('line',{x1:pad.l,y1:y,x2:w-pad.r,y2:y,stroke:'#E5E7EB','stroke-dasharray':n?'3 4':'0'}));}const gap=13,bw=Math.min(34,(w-pad.l-pad.r)/points.length-gap);points.forEach(([label,count],i)=>{const x=pad.l+12+i*((w-pad.l-pad.r)/points.length)+(bw/2);const height=(count/max)*(h-pad.t-pad.b-10);const rect=svgEl('rect',{x,y:h-pad.b-height,width:bw,height,rx:4,fill:'var(--accent)',opacity:.86});const title=svgEl('title');title.textContent=`${label}: ${count} runs`;rect.append(title);svg.append(rect);const tx=svgEl('text',{x:x+bw/2,y:h-7,'text-anchor':'middle',fill:'var(--muted)','font-size':9});tx.textContent=label;svg.append(tx);});target.append(svg);}
function statusBadge(status){return badge(status,status==='APPROVED'?'Approved':status==='PENDING'?'Pending':'Rejected');}
function sortValue(run,key){if(key==='status')return run.status;if(key==='risk')return Number(run.risk||0);if(key==='reason')return run.result?.decision_reasons?.[0]?.summary||'';return run[key]||'';}
function renderRuns(){const content=$('#runs-content');content.replaceChildren();const visible=dashboardRuns.filter(r=>(dashboardFilter==='All'||r.status===dashboardFilter)&&`${r.vendor} ${r.country} ${(r.result?.decision_reasons||[]).map(x=>x.summary).join(' ')}`.toLowerCase().includes(dashboardQuery.toLowerCase()));visible.sort((a,b)=>{const x=sortValue(a,sortBy),y=sortValue(b,sortBy);return (x>y?1:x<y?-1:0)*sortDir;});if(!dashboardRuns.length){const empty=node('div','empty-state');const ico=node('div','empty-icon');ico.append(icon('layout-dashboard'));empty.append(ico,node('h3','','No runs yet'),node('p','','Your vendor reviews will appear here. Run the sample cases to see the dashboard in action.'));const run=button('Run all samples','button-primary','play');run.addEventListener('click',runAllSamples);empty.append(run);content.append(empty);$('#pagination').classList.add('hidden');return;}if(!visible.length){const empty=node('div','empty-state');empty.append(node('h3','','No matching runs'),node('p','','Try another search or status filter.'));content.append(empty);$('#pagination').classList.add('hidden');return;}const pages=Math.ceil(visible.length/15);pageNumber=Math.min(pageNumber,pages);const slice=visible.slice((pageNumber-1)*15,pageNumber*15);const wrap=node('div','table-scroll');const table=node('table','runs-table');const thead=node('thead');const tr=node('tr');const cols=[['vendor','Vendor'],['country','Country'],['status','Status'],['risk','Risk'],['reason','Top reason'],['submitted_at','Time']];for(const [key,label] of cols){const th=node('th');const b=node('button','',`${label}${sortBy===key?(sortDir===1?' ↑':' ↓'):''}`);b.type='button';b.addEventListener('click',()=>{if(sortBy===key)sortDir=-sortDir;else{sortBy=key;sortDir=1;}renderRuns();});th.append(b);tr.append(th);}thead.append(tr);table.append(thead);const tbody=node('tbody');for(const run of slice){const row=node('tr');row.tabIndex=0;row.setAttribute('aria-label',`Open ${run.vendor}, ${run.status}`);row.addEventListener('click',()=>openDrawer(run.id));row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openDrawer(run.id);}});const vendor=node('td','vendor-cell',run.vendor||'Unknown vendor');const country=node('td','',run.country||'—');const status=node('td');status.append(statusBadge(run.status));const risk=node('td');const meter=node('div','risk-cell');const bar=node('span','mini-risk');const fill=node('span');fill.style.width=`${Math.max(0,Math.min(100,Number(run.risk)||0))}%`;fill.style.background=(run.risk||0)<35?'var(--green)':(run.risk||0)<65?'var(--amber)':'var(--red)';bar.append(fill);meter.append(bar,node('span','',String(run.risk??0)));risk.append(meter);const reason=node('td','reason-cell',run.result?.decision_reasons?.find(x=>x.stage!=='decision')?.summary||'No findings');reason.title=reason.textContent;const time=node('td','',formatTime(run.submitted_at));row.append(vendor,country,status,risk,reason,time);tbody.append(row);}table.append(tbody);wrap.append(table);content.append(wrap);if(pages>1){$('#pagination').classList.remove('hidden');$('#pagination').replaceChildren(node('span','',`Page ${pageNumber} of ${pages} · ${visible.length} runs`));const controls=node('div','page-buttons');const prev=node('button','','Previous');prev.disabled=pageNumber===1;prev.addEventListener('click',()=>{pageNumber--;renderRuns();});const next=node('button','','Next');next.disabled=pageNumber===pages;next.addEventListener('click',()=>{pageNumber++;renderRuns();});controls.append(prev,next);$('#pagination').append(controls);}else $('#pagination').classList.add('hidden');}
function drawFilters(){const root=$('#status-filters');root.replaceChildren();for(const label of ['All','APPROVED','PENDING','REJECTED']){const b=node('button',`filter-pill ${dashboardFilter===label?'is-selected':''}`,label==='All'?'All':label[0]+label.slice(1).toLowerCase());b.type='button';b.setAttribute('aria-pressed',String(dashboardFilter===label));b.addEventListener('click',()=>{dashboardFilter=label;pageNumber=1;drawFilters();renderRuns();});root.append(b);}}
async function loadDashboard(){renderDashboardSkeleton();try{dashboardRuns=await api('/api/runs');const total=dashboardRuns.length,counts={APPROVED:0,PENDING:0,REJECTED:0};let ms=0,fraud=0;for(const r of dashboardRuns){counts[r.status]=(counts[r.status]||0)+1;ms+=Number(r.result?.total_ms)||0;fraud+=(r.result?.decision_reasons||[]).filter(x=>x.severity==='fraud').length;}const k=$('#dashboard-kpis');k.replaceChildren(makeKpi('Total runs',total,'All recorded reviews','layout-dashboard'),makeKpi('Approved',counts.APPROVED,total?`${Math.round(counts.APPROVED/total*100)}% of runs`:'Ready for first review','check'),makeKpi('Pending',counts.PENDING,total?`${Math.round(counts.PENDING/total*100)}% of runs`:'Nothing awaiting review','clock'),makeKpi('Rejected',counts.REJECTED,total?`${Math.round(counts.REJECTED/total*100)}% of runs`:'No rejected runs','x'),makeKpi('Avg processing time',total?`${Math.round(ms/total)} ms`:'—',total?'Across all runs':'Measured at completion','activity'),makeKpi('Fraud flags caught',fraud,total?`Across ${total} runs`:'No flags found','shieldCheck'));drawStatusChart(dashboardRuns);drawTimeChart(dashboardRuns);drawFilters();renderRuns();}catch(e){$('#runs-content').replaceChildren(node('div','inline-error',`Could not load run history: ${e.message}`));}}
async function runAllSamples(){const b=$('#run-all');if(b){b.classList.add('button-loading');b.disabled=true;}try{await api('/api/run-samples',{method:'POST'});toast('Sample runs completed.');setPage('dashboard');}catch(e){toast(e.message,'error');}finally{if(b){b.classList.remove('button-loading');b.disabled=false;}}}

async function openDrawer(id){const drawer=$('#run-drawer'),back=$('#drawer-backdrop'),content=$('#drawer-content');drawer.classList.add('is-open');drawer.setAttribute('aria-hidden','false');back.classList.remove('hidden');requestAnimationFrame(()=>back.classList.add('is-open'));content.replaceChildren(node('div','skeleton','　'),node('div','skeleton','　'),node('div','skeleton','　'));drawerRun=null;try{const run=await api(`/api/runs/${encodeURIComponent(id)}`);drawerRun=run;content.replaceChildren();const header=node('div','drawer-header');header.append(node('h2','','Run details'));const close=node('button','icon-button');close.setAttribute('aria-label','Close run details');close.append(icon('close'));close.addEventListener('click',closeDrawer);header.append(close);content.append(header,renderDecision(run,content,true));const stagesCard=node('section','drawer-section');stagesCard.append(node('h3','','Verification stages'));const list=node('div','stepper-list');for(const e of run.events||[]){const row=stageRow(e.stage_id,e.name);row.classList.remove('idle');row.classList.add(e.status);row.dataset.status=e.status;$('.step-status',row).replaceChildren(icon(e.status==='pass'?'check':e.status==='warn'?'alert':e.status==='fail'?'x':'file'));$('.step-summary',row).textContent=e.summary;$('.step-duration',row).textContent=`${e.duration_ms||0} ms`;fillEvidence(row,e);list.append(row);}stagesCard.append(list);content.append(stagesCard);if(run.parent_run_id||run.previous_id)await loadDiff(run.parent_run_id||run.previous_id,content,true);}catch(e){content.replaceChildren(node('div','inline-error',e.message));}}
function closeDrawer(){const drawer=$('#run-drawer'),back=$('#drawer-backdrop');drawer.classList.remove('is-open');drawer.setAttribute('aria-hidden','true');back.classList.remove('is-open');setTimeout(()=>back.classList.add('hidden'),220);}
function flatten(v,path='',out={}){if(v&&typeof v==='object'&&!Array.isArray(v)){for(const [k,x] of Object.entries(v))flatten(x,path?`${path}.${k}`:k,out);}else out[path]=JSON.stringify(v);return out;}
function displayDiffValue(path,value){if(path==='documents'){try{const docs=JSON.parse(value||'[]');if(Array.isArray(docs))return docs.length?`${docs.length} document${docs.length===1?'':'s'} · ${docs.map(d=>d.type||'untitled').join(', ')}`:'No documents';}catch{}}return value??'—';}
async function loadDiff(parentId,target,isDrawer=false){try{const parent=await api(`/api/runs/${encodeURIComponent(parentId)}`);const current=isDrawer?drawerRun:currentRun;if(!current)return;const old=flatten(parent.payload),now=flatten(current.payload);const changes=[...new Set([...Object.keys(old),...Object.keys(now)])].filter(k=>old[k]!==now[k]);const previousFindings=(parent.result.decision_reasons||[]).filter(x=>x.stage!=='decision').map(x=>x.summary),newFindings=(current.result.decision_reasons||[]).filter(x=>x.stage!=='decision').map(x=>x.summary);const resolved=previousFindings.filter(x=>!newFindings.includes(x)),still=newFindings.filter(x=>previousFindings.includes(x)),introduced=newFindings.filter(x=>!previousFindings.includes(x));const panel=node('section','drawer-section diff-panel');const change=node('div','diff-status');change.append(badge(parent.result.status,parent.result.status[0]+parent.result.status.slice(1).toLowerCase()),icon('arrow'),badge(current.result.status,current.result.status[0]+current.result.status.slice(1).toLowerCase()));panel.append(change,node('h3','','Submission changes'));if(!changes.length)panel.append(node('p','helper','No submission fields changed.'));for(const key of changes){const row=node('div','diff-row');row.append(node('strong','',key));const vals=node('div','diff-values');vals.append(node('span','diff-old',displayDiffValue(key,old[key])),node('span','diff-new',displayDiffValue(key,now[key])));row.append(vals);panel.append(row);}for(const [title,items] of [['Resolved findings',resolved],['Still open',still],['New findings',introduced]]){panel.append(node('h3','diff-subtitle',title));const ul=node('ul','diff-list');if(!items.length)ul.append(node('li','','None'));else items.forEach(x=>ul.append(node('li','',x)));panel.append(ul);}target.append(panel);}catch(e){toast(`Could not load resubmission comparison: ${e.message}`,'error');}}

function renderRules(){const map=$('#decision-map');map.replaceChildren();for(const [title,desc,kind] of [['Approved','No fixable, blocking, or fraud findings.','approved'],['Pending','At least one correctable finding needs vendor follow-up.','pending'],['Rejected','A fraud or blocking finding requires rejection.','rejected']]){const c=node('section',`decision-outcome outcome-${kind}`);c.append(node('h3','',title),node('p','',desc));map.append(c);}const root=$('#rules-groups');root.replaceChildren();for(const [title,rules] of ruleGroups){const card=node('section','card rules-card');card.append(node('h2','',title));for(const [id,severity,description,why] of rules){const row=node('div','rule-line');const idchip=node('span','rule-id',id);const body=node('div','rule-text');body.append(node('div','',description));const whyline=node('span','rule-why',`Why this matters: ${why}`);const sev=node('span',`badge severity-${severity}`,severity);const meta=node('div','rule-meta');meta.append(idchip,sev);body.append(whyline);row.append(meta,body);card.append(row);}root.append(card);}}

function tabSetup(){for(const b of [$('#tab-form'),$('#tab-json')])b.addEventListener('click',()=>activateEditor(b=== $('#tab-json')?'json':'form'));$('#json-editor').addEventListener('input',()=>{if(!validateJson())return;try{const parsed=JSON.parse($('#json-editor').value);currentSubmission=parsed;if($('#panel-json').classList.contains('hidden')===false)syncFormValues(parsed);}catch{}});$('#format-json').addEventListener('click',()=>{if(!validateJson()){toast('Fix JSON syntax before formatting.','error');return;}const parsed=JSON.parse($('#json-editor').value);$('#json-editor').value=JSON.stringify(parsed,null,2);syncFormValues(parsed);toast('JSON formatted.');});}
function initNavigation(){for(const b of $$('.nav-item'))b.addEventListener('click',()=>setPage(b.dataset.page));$('#menu-open').append(icon('menu'));$$('.brand-mark').forEach(mark=>mark.append(icon('shieldCheck')));$('#menu-open').addEventListener('click',()=>document.body.classList.contains('mobile-open')?closeMobile():openMobile());$('#mobile-overlay').addEventListener('click',closeMobile);$('#drawer-backdrop').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();closeMobile();}});$$('.go-new').forEach(b=>b.addEventListener('click',()=>setPage('new')));}
function initActions(){ $('#run-process').addEventListener('click',()=>{let payload;if($('#panel-json').classList.contains('hidden')){payload=collectForm();if(!payload.legal_name||!payload.country){toast('Enter a legal name and country before running.','error');return;}}else{if(!validateJson()){toast('Correct the JSON errors before running.','error');return;}try{payload=JSON.parse($('#json-editor').value);}catch(e){toast(e.message,'error');return;}}if(parentForResubmit){const parent=parentForResubmit;parentForResubmit=null;resubmit(parent,payload);}else beginRun(payload);});$('#reset-form').addEventListener('click',resetForm);$('#run-all').addEventListener('click',runAllSamples);$('#dashboard-refresh').addEventListener('click',loadDashboard);$('#reset-demo').addEventListener('click',async()=>{if(!confirm('Reset demo data? This removes saved runs and restores the seeded vendor master.'))return;try{const r=await api('/api/admin/reset',{method:'POST'});dashboardRuns=[];currentRun=null;renderLiveEmpty();toast(`Demo data reset${r.runs?` and ${r.runs} samples seeded`:''}.`);setPage('dashboard');}catch(e){toast(e.message,'error');}});$('#run-search').addEventListener('input',e=>{dashboardQuery=e.target.value;pageNumber=1;renderRuns();});}
async function resubmit(parent,payload){const ctl=$('#run-process');ctl.classList.add('button-loading');ctl.disabled=true;try{const run=await api(`/api/runs/${encodeURIComponent(parent)}/resubmit`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});currentRun=run;parentForResubmit=null;setPage('live');finishRun(run);toast('Resubmission complete. Review the before-and-after comparison.');}catch(e){toast(e.message,'error');parentForResubmit=parent;}finally{ctl.classList.remove('button-loading');ctl.disabled=false;}}
async function init(){initNavigation();tabSetup();initActions();renderRules();renderForm(emptySubmission());renderLiveEmpty();try{samples=await api('/api/samples');renderSamples();}catch(e){$('#sample-grid').replaceChildren(node('div','inline-error',`Samples could not be loaded: ${e.message}`));}$('#sample-count').textContent=`${Object.keys(samples).length} examples`;}
new MutationObserver(()=>{const list=$('#document-list');if(list&&pendingDocumentRows.length){list.append(...pendingDocumentRows);pendingDocumentRows=[];}}).observe(document.body,{childList:true,subtree:true});
const baseFormChanged=formChanged;formChanged=function(){baseFormChanged();if($('#panel-json').classList.contains('hidden'))$('#json-validity').classList.add('hidden');};
const baseSelectSample=selectSample;selectSample=function(key){const parent=parentForResubmit;baseSelectSample(key);if(parent)parentForResubmit=parent;};
const baseInit=init;init=async function(){await baseInit();activateEditor('form');};
init();
